#endif /* DO_SUBTREE_WALK */
#if DEBUG
  if (debug_level >= 5) {
    fprintf(f_debug, "Walking IL tree, entry kind = %s\n",
                     il_entry_kind_names[(int)entry_kind]);
  }  /* if */
#endif /* DEBUG */
