        scalar("highest_virtual_function_number", ctsp->highest_virtual_function_number);
        scalar("next_negative_virtual_table_index", ctsp->next_negative_virtual_table_index);
        scalar("first_vcall_offset_index", ctsp->first_vcall_offset_index);
        scalar("virtual_function_info_offset", ctsp->virtual_function_info_offset);
        scalar("decl_modifiers", ctsp->decl_modifiers);
        scalar("orig_type_kind", ctsp->orig_type_kind);
        scalar("inheritance_kind", ctsp->inheritance_kind);
        scalar("inheritance_kind_is_explicit", ctsp->inheritance_kind_is_explicit);
