        scalar("contains_error_cached", ctsp->contains_error_cached);
        scalar("contains_local_type", ctsp->contains_local_type);
        scalar("contains_local_type_cached", ctsp->contains_local_type_cached);
        scalar("contains_unnamed_namespace_type", ctsp->contains_unnamed_namespace_type);
        scalar("contains_unnamed_namespace_type_cached", ctsp->contains_unnamed_namespace_type_cached);
        scalar("does_not_contain_parentless_lambda_in_default_argument", ctsp->does_not_contain_parentless_lambda_in_default_argument);
        scalar("does_not_contain_deprecated_or_unavailable_type", ctsp->does_not_contain_deprecated_or_unavailable_type);
        scalar("anonymous_union_kind", ctsp->anonymous_union_kind);
